package net.officefloor.hq.app.claim;

import java.util.ArrayList;
import java.util.List;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.session.ChangedBy;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/**
 * The paste box's lines of name,amount,date,note (the note may hold commas; the date may be blank for the sheet's
 * today; the note may be absent; blank lines are skipped). Each line's fields are checked with the claim form's
 * rules; a refusal names the line. Publishes them parsed, in order, with the user making the change.
 */
public class ValidatePaste {

    static final int MAX_LINES = 1000;

    public void validate(@RequestBody PasteRequest request, Out<PasteLines> pasted, Out<ChangedBy> changedBy)
            throws BadRequestException {
        ChangedBy by = ChangedBy.of(request == null ? null : request.by());
        String text = request == null || request.lines() == null ? "" : request.lines();
        List<PasteLine> lines = new ArrayList<>();
        String[] typed = text.split("\\r?\\n");
        for (int i = 0; i < typed.length; i++) {
            if (typed[i].trim().isEmpty()) {
                continue;
            }
            String[] fields = typed[i].split(",", 4);
            String name = fields[0].trim();
            if (name.isEmpty() || fields.length < 2) {
                throw new BadRequestException("Line " + (i + 1) + ": enter name,amount,date,note");
            }
            try {
                lines.add(new PasteLine(name, ValidateClaim.parse(new ClaimRequest(fields[1],
                        fields.length > 2 ? fields[2] : "", fields.length > 3 ? fields[3] : "", null, by.name()))));
            } catch (BadRequestException e) {
                throw new BadRequestException("Line " + (i + 1) + ": " + e.getMessage());
            }
        }
        if (lines.isEmpty()) {
            throw new BadRequestException("Paste at least one line of name,amount,date,note");
        }
        if (lines.size() > MAX_LINES) {
            throw new BadRequestException("Paste at most " + MAX_LINES + " lines at once");
        }
        pasted.set(new PasteLines(lines));
        changedBy.set(by);
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.access.SettingRepository;
import net.officefloor.hq.app.holiday.HolidayRepository;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupSnapshot;
import net.officefloor.hq.app.session.ChangedBy;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.hq.app.sheet.SheetResponse;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/**
 * Adds a DRAFT claim per pasted line, in order, for the person of that name (case and surrounding spaces ignored).
 * Every line is first checked as the claim form checks a new claim (person on the sheet, correction, closed period,
 * retirement); one refusal refuses them all before anything is written. Each added claim is recorded as CLAIM_ADDED,
 * then the rollup lines for what the paste moved.
 */
public class AddPastedClaims {

    public void add(@Val SheetResponse sheet, @Val PasteLines pasted, @Val ChangedBy by, PersonRepository people,
            ClaimRepository claims, SheetRepository sheets, PeriodRepository periods, SettingRepository settings,
            HolidayRepository holidays, Rollup rollup, Audit audit, ClaimLog log, Out<PasteResponse> response) throws BadRequestException {
        LocalDate today = settings.entryDate(sheet.id(), sheets.today(sheet.id()));
        List<Person> persons = new ArrayList<>();
        int n = 0;
        for (PasteLine line : pasted.lines()) {
            n++;
            Person person = people.findByName(sheet.id(), line.name());
            if (person == null) {
                throw new BadRequestException("Line " + n + ": " + line.name() + " is not on this sheet");
            }
            ClaimInput input = line.input();
            LocalDate date = input.date() != null ? input.date() : today;
            try {
                RefuseBadCorrection.refuse(input, sheet.id(), person.getId(), claims);
                RefuseClosedDate.refuse(sheet.id(), BuildClaim.dueBy(person, date, settings, holidays), periods);
                RefuseRetiredDate.refuse(person, date);
            } catch (BadRequestException e) {
                throw new BadRequestException("Line " + n + ": " + e.getMessage());
            }
            persons.add(person);
        }

        RollupSnapshot before = rollup.snapshot(sheet.id());
        for (int i = 0; i < persons.size(); i++) {
            Person person = persons.get(i);
            ClaimInput input = pasted.lines().get(i).input();
            LocalDate date = input.date() != null ? input.date() : today;
            Claim claim = claims.insert(sheet.id(), person.getId(), input.amount(), date, input.note(),
                    input.corrects(), BuildClaim.terms(person, date, settings));
            if (periods.softClosedOn(sheet.id(), claim.getDueBy())) {
                claims.markLate(claim);
            }
            audit.record(ClaimAudit.line("CLAIM_ADDED", claim, by, person.getName()));
            if (claim.isLateEntry()) {
                audit.record(ClaimAudit.line("LATE_ENTRY", claim, by, person.getName()));
            }
            log.record(claim, by);
        }
        rollup.record(sheet.id(), before, by);
        response.set(new PasteResponse(persons.size()));
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.sql.Date;
import java.sql.PreparedStatement;
import java.time.LocalDate;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.officefloor.hq.app.holiday.HolidayRepository;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.stereotype.Repository;

/** The claims on each sheet; ids are assigned in the order claims are added, and claims are listed newest first (a moved claim as its new person's newest). */
@Repository
public class ClaimRepository {

    // A correction rounds by the date of the claim it corrects (a claim of the same person, by number).
    private static final String COLUMNS = "id, sheet_id, person_id, amount, claim_date, note, status, claim_number, settled_due, opened_by, stated, stated_due, corrects, due_from, terms, deferred_until, proofs, split_from, late_entry, reminded_on,"
            + " (SELECT o.claim_date FROM claim o WHERE o.sheet_id = claim.sheet_id AND o.person_id = claim.person_id"
            + " AND o.claim_number = claim.corrects) AS corrected_date";

    private static final RowMapper<Claim> ROW = (rs, n) -> {
        Claim claim = new Claim(rs.getLong("id"), rs.getString("sheet_id"),
                rs.getLong("person_id"), rs.getBigDecimal("amount"), rs.getObject("claim_date", LocalDate.class),
                rs.getString("note"), ClaimStatus.valueOf(rs.getString("status")),
                rs.getString("claim_number"), rs.getBigDecimal("settled_due"),
                rs.getString("opened_by"), rs.getBoolean("stated"), rs.getBigDecimal("stated_due"),
                rs.getString("corrects"));
        claim.setDueFrom(rs.getObject("due_from", LocalDate.class));
        claim.setTerms(rs.getInt("terms"));
        claim.setDeferredUntil(rs.getObject("deferred_until", LocalDate.class));
        claim.setProofs(rs.getInt("proofs"));
        claim.setSplitFrom(rs.getString("split_from"));
        claim.setLateEntry(rs.getBoolean("late_entry"));
        claim.setRemindedOn(rs.getObject("reminded_on", LocalDate.class));
        LocalDate corrected = rs.getObject("corrected_date", LocalDate.class);
        if (corrected != null) {
            claim.setRoundOn(corrected);
        }
        return claim;
    };

    private final JdbcTemplate jdbc;

    private final HolidayRepository holidays;

    public ClaimRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
        this.holidays = new HolidayRepository(jdbc);
    }

    /** Work out each claim's due-by from the date it counts from, its terms and its sheet's holidays as they stand now. */
    private List<Claim> due(List<Claim> claims) {
        Map<String, Set<LocalDate>> bySheet = new HashMap<>();
        for (Claim claim : claims) {
            Set<LocalDate> off = bySheet.computeIfAbsent(claim.getSheetId(), holidays::set);
            claim.setDueBy(HolidayRepository.businessDay(claim.getDueFrom(), claim.getTerms(), off));
        }
        return claims;
    }

    /** The person's claims, newest first. */
    public List<Claim> listOf(String sheetId, long personId) {
        return due(jdbc.query("SELECT " + COLUMNS + " FROM claim WHERE sheet_id = ? AND person_id = ? ORDER BY listed DESC", ROW,
                sheetId, personId));
    }

    /** Bind the claim to a figure (null: n/a), or unbind it when not {@code stated}. */
    public void bind(long id, boolean stated, BigDecimal statedDue) {
        jdbc.update("UPDATE claim SET stated = ?, stated_due = ? WHERE id = ?", stated, statedDue, id);
    }

    /** Unbind every claim of the person from its statement figure, so each is live again. */
    public void unbindAllOf(String sheetId, long personId) {
        jdbc.update("UPDATE claim SET stated = FALSE, stated_due = NULL WHERE sheet_id = ? AND person_id = ?",
                sheetId, personId);
    }

    /** The sheet's claims, newest first. */
    public List<Claim> list(String sheetId) {
        return due(jdbc.query("SELECT " + COLUMNS + " FROM claim WHERE sheet_id = ? ORDER BY listed DESC", ROW, sheetId));
    }

    /** Whether the person has a SETTLED claim with this number on the sheet. */
    public boolean settledNumbered(String sheetId, long personId, String number) {
        return jdbc.queryForObject("SELECT COUNT(*) FROM claim WHERE sheet_id = ? AND person_id = ? AND claim_number = ? AND status = ?",
                Integer.class, sheetId, personId, number, ClaimStatus.SETTLED.name()) > 0;
    }

    public Claim find(String sheetId, long id) {
        return due(jdbc.query("SELECT " + COLUMNS + " FROM claim WHERE sheet_id = ? AND id = ?", ROW, sheetId, id))
                .stream().findFirst().orElse(null);
    }

    /** Add a draft claim, its due-by counting {@code terms} business days from its date for good. */
    public Claim insert(String sheetId, long personId, BigDecimal amount, LocalDate date, String note, String corrects,
            int terms) {
        long listed = nextListed(sheetId);
        GeneratedKeyHolder keys = new GeneratedKeyHolder();
        jdbc.update(con -> {
            PreparedStatement ps = con.prepareStatement(
                    "INSERT INTO claim (sheet_id, person_id, amount, claim_date, note, corrects, listed, due_from, terms) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)",
                    new String[] { "id" });
